define(['core_user/repository'],function(R){'use strict';var PREF='local_unics_shell_rail_collapsed',LS='unics_shell_rail_collapsed',C='unics-shell-rail--collapsed',OPEN='is-open';function setCollapsed(rail,t,collapsed){rail.classList.toggle(C,collapsed);var l=collapsed?'Развернуть меню':'Свернуть меню';t.setAttribute('aria-expanded',collapsed?'false':'true');t.setAttribute('aria-label',l);t.setAttribute('title',l);}return{init:function(){var rail=document.querySelector('.unics-shell-rail');if(!rail)return;var t=rail.querySelector('.unics-shell-rail__toggle');if(t){try{var ls=window.localStorage.getItem(LS);if(ls!==null){var c=ls==='1';if(c!==rail.classList.contains(C))setCollapsed(rail,t,c);}}catch(e){}t.addEventListener('click',function(){var collapsed=!rail.classList.contains(C);setCollapsed(rail,t,collapsed);try{window.localStorage.setItem(LS,collapsed?'1':'0');}catch(e){}R.setUserPreference(PREF,collapsed?'1':'0').catch(function(){});});}var burger=document.querySelector('.unics-shell-rail__burger'),backdrop=document.querySelector('.unics-shell-rail__backdrop');function focusable(){return Array.prototype.filter.call(rail.querySelectorAll('a[href], button:not([disabled])'),function(el){return el.offsetParent!==null;});}function onKey(e){if(e.key==='Escape'){closeRail();return;}if(e.key==='Tab'){var f=focusable();if(!f.length)return;var first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}function openRail(){rail.classList.add(OPEN);if(burger)burger.setAttribute('aria-expanded','true');if(backdrop){backdrop.hidden=false;window.requestAnimationFrame(function(){backdrop.classList.add('is-visible');});}document.body.style.overflow='hidden';document.addEventListener('keydown',onKey);var f=focusable();if(f.length)f[0].focus();}function closeRail(){if(!rail.classList.contains(OPEN))return;rail.classList.remove(OPEN);if(burger)burger.setAttribute('aria-expanded','false');if(backdrop){backdrop.classList.remove('is-visible');backdrop.hidden=true;}document.body.style.overflow='';document.removeEventListener('keydown',onKey);if(burger)burger.focus();}if(burger)burger.addEventListener('click',function(){if(rail.classList.contains(OPEN))closeRail();else openRail();});if(backdrop)backdrop.addEventListener('click',closeRail);rail.addEventListener('click',function(e){if(e.target.closest('.unics-shell-rail__item'))closeRail();});}};});
